package cn.zhuatech.expenseai; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import java.util.regex.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class ExpenseAiApiIntegrationTests{@Autowired MockMvc mvc;String token;@BeforeEach void login()throws Exception{String j=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"operator\",\"password\":\"Demo@2026\"}")).andReturn().getResponse().getContentAsString();Matcher m=Pattern.compile("\\\"token\\\":\\\"([^\\\"]+)\\\"").matcher(j);if(!m.find())throw new AssertionError();token=m.group(1);}@Test void audits()throws Exception{mvc.perform(post("/api/ai/expense/audit").header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content("{\"expenseNo\":\"EX-88\",\"employeeNo\":\"E-09\",\"amount\":18000,\"receiptVerified\":false,\"duplicateReceipt\":true,\"policyOverrunPercent\":60,\"weekendOrHoliday\":true,\"merchantRiskScore\":88}")).andExpect(status().isOk()).andExpect(jsonPath("$.data.decision").value("BLOCK"));}}
